type Status = "open" | "done";
type Task = { id: number; title: string; status: Status; createdAt: string; tags: string[]; due?: string; completedAt?: string };
type Store = { tasks: Task[]; nextId: number };

const file = process.env.TASKBOARD_FILE || ".taskboard.json";
const fail = (message: string): never => { console.error(message); process.exit(1); };
const dateRE = /^\d{4}-\d{2}-\d{2}$/;
function validDate(value: string): boolean {
  if (!dateRE.test(value)) return false;
  const d = new Date(`${value}T00:00:00Z`);
  return !Number.isNaN(d.valueOf()) && d.toISOString().slice(0, 10) === value;
}
function load(): Store {
  const f = Bun.file(file);
  if (!f.size) return { tasks: [], nextId: 1 };
  let data: unknown;
  try { data = JSON.parse(awaitText(f)); } catch { fail("Malformed database"); }
  if (!data || typeof data !== "object" || !Array.isArray((data as Store).tasks)) fail("Malformed database");
  const s = data as Store;
  if (!Number.isInteger(s.nextId) || s.nextId < 1) fail("Malformed database");
  for (const t of s.tasks) if (!t || !Number.isInteger(t.id) || typeof t.title !== "string" || (t.status !== "open" && t.status !== "done") || !Array.isArray(t.tags)) fail("Malformed database");
  return s;
}
function awaitText(f: ReturnType<typeof Bun.file>): string { return require("fs").readFileSync(file, "utf8"); }
async function save(s: Store) {
  const fs = require("fs");
  const tmp = `${file}.tmp-${process.pid}-${Date.now()}`;
  fs.writeFileSync(tmp, JSON.stringify(s) + "\n", { encoding: "utf8", flag: "wx" });
  fs.renameSync(tmp, file);
}
function out(value: unknown) { console.log(JSON.stringify(value)); }
function arg(name: string, args: string[]): string | undefined { const i = args.indexOf(name); return i < 0 ? undefined : args[i + 1]; }
function checkFlags(args: string[], allowed: string[]) { for (let i = 0; i < args.length; i++) if (args[i].startsWith("--") && !allowed.includes(args[i])) fail(`Unknown flag: ${args[i]}`); }

